// A mesma chave vai em todas as tentativas da mesma cobrança.
// O serviço de pagamento guarda a chave e devolve o resultado anterior
// em vez de cobrar de novo.
const idempotencyKey = `charge-${order.id}`;

await http.post("/charges", { orderId: order.id, amount: order.total }, {
	headers: { "Idempotency-Key": idempotencyKey },
	timeoutMs: 2000,
	retries: 3,
});

// The same key goes with every attempt of the same charge.
// The payment service stores the key and returns the previous result
// instead of charging again.
const idempotencyKey = `charge-${order.id}`;

await http.post("/charges", { orderId: order.id, amount: order.total }, {
	headers: { "Idempotency-Key": idempotencyKey },
	timeoutMs: 2000,
	retries: 3,
});

// La misma clave va en todos los intentos del mismo cobro.
// El servicio de pagos guarda la clave y devuelve el resultado anterior
// en lugar de cobrar de nuevo.
const idempotencyKey = `charge-${order.id}`;

await http.post("/charges", { orderId: order.id, amount: order.total }, {
	headers: { "Idempotency-Key": idempotencyKey },
	timeoutMs: 2000,
	retries: 3,
});
